package indicator_test

import (
	"strings"
	"testing"

	"github.com/shopspring/decimal"
	"github.com/stretchr/testify/require"

	"github.com/warden-stock/warden-stock-data/internal/indicator"
)

func TestSnapshotValuesJSONFixedDecimals(t *testing.T) {
	vals := map[string]decimal.Decimal{
		"ma5":      decimal.RequireFromString("10.98"),
		"macd_bar": decimal.RequireFromString("0."),
		"rsi6":     decimal.RequireFromString("59.4940647158157301"),
	}
	b, err := indicator.SnapshotValuesJSON(vals)
	require.NoError(t, err)
	s := string(b)
	require.Less(t, len(s), 200, "payload should stay compact")
	require.Contains(t, s, `"ma5":"10.9800"`)
	require.Contains(t, s, `"macd_bar":"0.0521"`)
	require.Contains(t, s, `"rsi6":"59.4941"`)
	require.False(t, strings.Contains(s, "641075"))
}
